replacement=r'''function locationTypeClass(type){return`location-type-${['home','work','business','private'].includes(type)?type:'other'}`}
function locationTypeIcon(type){return type==='home'?'🏠':type==='work'?'🧰':type==='business'?'🏢':type==='private'?'👤':'📍'}
function locationShareStatus(value){const v=['ask','always'].includes(value)?value:'never',label=v==='ask'?'Rit delen: vraag mij':v==='always'?'Rit delen: altijd tonen':'Rit delen: nooit';return`<span class="location-share-status ${v}" title="${attr(label)}" aria-label="${attr(label)}">↗</span>`}
function locationHasGps(l){return parseNum(l?.lat)!=null&&parseNum(l?.lng)!=null}
function locationLinkStatus(l){const hasAddress=!!String(l?.address||'').trim(),hasGps=locationHasGps(l);let cls='none',label='Adres en GPS ontbreken',icon='A·⌖';if(hasAddress&&hasGps){cls='complete';label='Adres en GPS gekoppeld';icon='A↔⌖'}else if(hasAddress){cls='address-only';label='Adres aanwezig · GPS kan worden aangevuld';icon='A→⌖'}else if(hasGps){cls='gps-only';label='GPS aanwezig · adres kan worden aangevuld';icon='⌖→A'}return`<span class="location-link-status ${cls}" title="${attr(label)}" aria-label="${attr(label)}">${icon}</span>`}
function locationStatusIcons(l){return`<div class="location-status-icons">${locationShareStatus(l.shareRide||'never')}${locationLinkStatus(l)}</div>`}
function locationSortMode(){return data.settings.locationSortMode==='alpha'?'alpha':'smart'}
function settingsMomentOrigin(){return data.locations.find(x=>x.id===settingsLocationOriginId)||data.lastEndpoint?.location||inferLast()?.location||null}
function locationMomentScore(l,origin,moment=new Date(),suggested=null){let score=(+l.useCount||0)*.15;if(origin&&sameLoc(l,origin))score-=100;if(suggested&&sameLoc(l,suggested))score+=60;if(origin?.type==='home'&&l.type==='work')score+=18;if(origin?.type==='work'&&l.type==='home')score+=18;if((isConfiguredPrivateDay(moment)||isConfiguredPrivateTime(moment))&&l.type==='private')score+=12;const now=new Date(moment),nowMin=now.getHours()*60+now.getMinutes(),weekday=now.getDay(),weekend=weekday===0||weekday===6,windowMin=destinationTimeWindowHours()*60,dayMs=86400000;const relevant=sortedTrips().filter(t=>sameLoc(t.destination,l)&&(!origin||sameLoc(t.origin,origin))).slice(0,60);for(const t of relevant){const d=new Date(t.departureTime);if(Number.isNaN(d.getTime()))continue;const age=Math.max(0,(now-d)/dayMs),thenMin=d.getHours()*60+d.getMinutes(),raw=Math.abs(thenMin-nowMin),diff=Math.min(raw,1440-raw);score+=Math.max(0,7-age*.12);if(d.getDay()===weekday)score+=4;if(((d.getDay()===0||d.getDay()===6)===weekend))score+=2;if(diff<=windowMin)score+=8*Math.max(0,1-diff/windowMin)}return score}
function sortedSettingsLocations(){const arr=[...data.locations];if(locationSortMode()==='alpha')return arr.sort((a,b)=>a.name.localeCompare(b.name,'nl',{sensitivity:'base'}));const origin=settingsMomentOrigin(),moment=new Date(),suggested=origin?suggestDestination(origin,moment).location:null;return arr.sort((a,b)=>locationMomentScore(b,origin,moment,suggested)-locationMomentScore(a,origin,moment,suggested)||a.name.localeCompare(b.name,'nl',{sensitivity:'base'}))}
function locationSortControls(){const mode=locationSortMode();return`<div class="location-sort" aria-label="Locaties sorteren"><button type="button" class="${mode==='smart'?'active':''}" data-action="location-sort" data-mode="smart">◎ Logisch</button><button type="button" class="${mode==='alpha'?'active':''}" data-action="location-sort" data-mode="alpha">A–Z Naam</button></div>`}
function locationInlineDetails(l){const gps=coords(l)||'Niet vastgelegd',address=String(l.address||'').trim()||'Niet vastgelegd';return`<div class="location-inline-details"><div class="location-inline-grid"><div class="location-inline-item"><span>Type</span><strong>${locationTypeIcon(l.type)} ${esc(typeLabel(l.type))}</strong></div><div class="location-inline-item"><span>Rit delen</span><strong>${esc(shareRideLabel(l.shareRide||'never'))}</strong></div><div class="location-inline-item"><span>GPS</span><strong>${esc(gps)}</strong></div><div class="location-inline-item"><span>Gebruikt</span><strong>${odo(l.useCount||0)}×</strong></div></div><div class="location-inline-address"><strong>Adres</strong><br>${esc(address)}</div></div>`}
function locationSwipeRow(l){const expanded=expandedLocationId===l.id;return`<div class="location-entry ${expanded?'expanded':''}" data-id="${l.id}"><div class="swipe-row location-swipe-row" data-swipe-kind="location" data-id="${l.id}">${swipeActions('location',l.id)}<div class="swipe-surface location-item location-swipe-surface ${locationTypeClass(l.type)}" data-action="location-toggle" data-id="${l.id}"><div class="location-main"><strong>${esc(l.name)}</strong><small>${esc(l.address||coords(l)||'Geen adres/GPS')}</small></div>${locationStatusIcons(l)}<div class="chev">›</div></div></div>${expanded?locationInlineDetails(l):''}</div>`}
function settingsLocations(){const arr=sortedSettingsLocations();return`${locationSortControls()}${arr.length?`<div class="location-list">${arr.map(locationSwipeRow).join('')}</div>`:'<div class="hint" style="margin-top:12px">Nog geen locaties opgeslagen.</div>'}`}
function refreshSettingsLocationList(){const wrap=document.getElementById('settingsLocationListWrap');if(wrap)wrap.innerHTML=settingsLocations()}
'''
