refresh=r'''async function refreshSettingsLocationState(){const token=++settingsLocationCheck,wrap=document.getElementById('locationQuickActions'),status=document.getElementById('locationCurrentStatus');if(!wrap||!status||view!=='settings')return;if(!navigator.geolocation){status.textContent='GPS is niet beschikbaar op dit apparaat.';return}try{const g=await getPosition();if(token!==settingsLocationCheck||view!=='settings')return;const currentWrap=document.getElementById('locationQuickActions'),currentStatus=document.getElementById('locationCurrentStatus');if(!currentWrap||!currentStatus)return;const match=matches(g)[0]||null;settingsLocationOriginId=match?.location?.id||null;if(match){currentWrap.classList.add('known');currentWrap.innerHTML=`<button type="button" class="btn secondary current-known" data-action="edit-location" data-id="${match.location.id}">✓ Bekend</button><button type="button" class="btn secondary" data-action="add-location">Nieuwe locatie +</button>`;currentStatus.className='location-current-status known';currentStatus.textContent=`Huidige locatie is al opgeslagen als ${match.location.name}.`}else{currentWrap.classList.remove('known');currentStatus.className='location-current-status';currentStatus.textContent='Huidige locatie is nog niet opgeslagen.'}if(locationSortMode()==='smart')refreshSettingsLocationList()}catch(e){if(token!==settingsLocationCheck||view!=='settings')return;settingsLocationOriginId=null;const currentStatus=document.getElementById('locationCurrentStatus');if(currentStatus){currentStatus.className='location-current-status';currentStatus.textContent='Huidige locatie kon niet worden gecontroleerd.'}if(locationSortMode()==='smart')refreshSettingsLocationList()}}
'''
replace_section('async function refreshSettingsLocationState(){','function renderSettings(){',refresh,'refresh location state')

