form_funcs=r'''function locationTypeOption(value,icon,label,current){return`<label class="location-choice type-${value}"><input type="radio" name="type" value="${value}" ${current===value?'checked':''} required><span><b class="choice-icon">${icon}</b>${label}</span></label>`}
function locationShareOption(value,icon,label,current){return`<label class="location-choice"><input type="radio" name="shareRide" value="${value}" ${current===value?'checked':''} required><span><b class="choice-icon">${icon}</b>${label}</span></label>`}
function openLocation(id=null,current=false){settingsLocationsOpen=true;const l=id?data.locations.find(x=>x.id===id):null,build=g=>{openModal(`<div class="modal-head"><h2>${l?'Locatie wijzigen':'Locatie toevoegen'}</h2><button class="close" data-action="close">×</button></div><form id="locationForm" onsubmit="return false"><input type="hidden" name="id" value="${l?.id||''}">${field('Naam','name',l?.name||'')}${field('Adres','address',l?.address||'')}<button type="button" class="btn secondary full" data-action="gps-location">Gebruik huidige GPS</button>${field('Latitude','lat',l?.lat??g?.lat??'','text')}${field('Longitude','lng',l?.lng??g?.lng??'','text')}<div class="location-link-hint"><strong>Adres ↔ GPS</strong><br>Alleen ontbrekende gegevens worden automatisch aangevuld. Bestaande waarden blijven staan. Huidige GPS overschrijft bewust alleen de coördinaten om ze nauwkeuriger te maken.</div><div class="osm-attribution">Adreszoeking via OpenStreetMap Nominatim · <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">© OpenStreetMap-bijdragers</a></div><div class="form-group"><label>Type</label><div class="location-choice-grid type">${locationTypeOption('home','🏠','Thuis',l?.type||'other')}${locationTypeOption('work','🧰','Werk',l?.type||'other')}${locationTypeOption('business','🏢','Zakelijk',l?.type||'other')}${locationTypeOption('private','👤','Privé',l?.type||'other')}${locationTypeOption('other','📍','Overig',l?.type||'other')}</div></div><div class="form-group"><label>Rit delen</label><div class="location-choice-grid share">${locationShareOption('never','⊘','Nooit',l?.shareRide||'never')}${locationShareOption('ask','?','Vraag mij',l?.shareRide||'never')}${locationShareOption('always','↗','Altijd',l?.shareRide||'never')}</div><div class="hint" style="margin-top:6px">Bij Vraag mij krijg je na vertrek een eenmalige vraag. Bij Altijd blijft Deel rit beschikbaar tijdens de actieve rit.</div></div><div class="hint">Vul minimaal naam, adres of GPS in.</div><div id="locationStatus" class="hint"></div><button type="button" class="btn full" data-action="save-location">Locatie opslaan</button></form>`);setTimeout(()=>autoCompleteLocationForm(),0)};if(current)getPosition().then(build).catch(e=>{toast(e.message);build(null)});else build(null)}
async function fillGps(){const f=document.getElementById('locationForm');if(!f)return;const g=await getPosition();f.elements.lat.value=(+g.lat).toFixed(6);f.elements.lng.value=(+g.lng).toFixed(6);setLocationStatus('GPS verfijnd met je huidige locatie.');await autoFillLocationFromGps();toast('GPS verfijnd met huidige locatie.')}
async function saveLocation(){const f=document.getElementById('locationForm');if(!f)throw new Error('Locatieformulier niet gevonden.');await autoCompleteLocationForm();const fd=new FormData(f),id=String(fd.get('id')||uid()),old=data.locations.find(x=>x.id===id),rawName=String(fd.get('name')||'').trim(),address=String(fd.get('address')||'').trim(),lat=parseNum(fd.get('lat')),lng=parseNum(fd.get('lng'));if((lat==null)!=(lng==null))throw new Error('Vul beide GPS-coördinaten in of laat beide leeg.');if(lat!=null&&Math.abs(lat)>90)throw new Error('Latitude is ongeldig.');if(lng!=null&&Math.abs(lng)>180)throw new Error('Longitude is ongeldig.');if(!rawName&&!address&&lat==null)throw new Error('Vul minimaal naam, adres of GPS in.');const name=rawName||address||`Locatie ${lat.toFixed(5)}, ${lng.toFixed(5)}`,loc={id,name,address,lat,lng,type:String(fd.get('type')||'other'),shareRide:['ask','always'].includes(String(fd.get('shareRide')||''))?String(fd.get('shareRide')):'never',useCount:old?.useCount||0,createdAt:old?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()},i=data.locations.findIndex(x=>x.id===id);if(i>=0)data.locations[i]=loc;else data.locations.push(loc);save();if(!JSON.parse(localStorage.getItem(KEY)||'{}').locations?.some(x=>x.id===id))throw new Error('Locatie niet teruggevonden in opslag.');expandedLocationId=id;settingsLocationsOpen=true;closeModal();render();toast('Locatie opgeslagen: '+name)}
'''
